import React, { useState, useEffect } from 'react';
import Map, { Marker, Popup, NavigationControl } from 'react-map-gl/maplibre';
import 'maplibre-gl/dist/maplibre-gl.css';
import { Plane, Truck, MapPin, Compass, Layers, X, Camera } from 'lucide-react';

export default function FleetMap({ telemetryData, vehicleById, theme, selectedVehicle, setSelectedVehicle, activeTraces }) {
  const [viewState, setViewState] = useState({
    longitude: -122.4194,
    latitude: 37.7749,
    zoom: 15,
    pitch: 65,
    bearing: -20
  });

  const [isHudExpanded, setIsHudExpanded] = useState(true);
  const [history, setHistory] = useState({});

  useEffect(() => {
    if (selectedVehicle && telemetryData[selectedVehicle]) {
      setViewState(prev => ({
        ...prev,
        longitude: telemetryData[selectedVehicle].longitude,
        latitude: telemetryData[selectedVehicle].latitude,
        transitionDuration: 1200
      }));
    }
  }, [selectedVehicle, telemetryData]);

  useEffect(() => {
    setHistory(prev => {
      const next = { ...prev };
      Object.values(telemetryData).forEach(pos => {
        const vId = pos.vehicle_id;
        if (!next[vId]) next[vId] = [];

        const alt = pos.altitude || 0;
        const last = next[vId][next[vId].length - 1];

        if (!last || last.lng !== pos.longitude || last.lat !== pos.latitude || last.alt !== alt) {
          next[vId] = [...next[vId], { lng: pos.longitude, lat: pos.latitude, alt }];
          if (next[vId].length > 40) next[vId].shift();
        }
      });
      return next;
    });
  }, [telemetryData]);

  const mapStyle = {
    version: 8,
    sources: {
      osm: {
        type: 'raster',
        tiles: [
          'https://a.tile.openstreetmap.org/{z}/{x}/{y}.png',
          'https://b.tile.openstreetmap.org/{z}/{x}/{y}.png',
          'https://c.tile.openstreetmap.org/{z}/{x}/{y}.png'
        ],
        tileSize: 256,
        attribution: '&copy; OpenStreetMap Contributors'
      }
    },
    layers: [{ id: 'osm', type: 'raster', source: 'osm', minzoom: 0, maxzoom: 19 }]
  };

  const isDark = theme === 'dark';
  const hudBg = isDark ? 'var(--bg-glass, rgba(18, 18, 22, 0.95))' : 'rgba(255, 255, 255, 0.95)';
  const textColor = isDark ? '#fff' : '#111';
  const subtextColor = isDark ? '#888' : '#555';
  const borderColor = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.1)';
  const btnBg = isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.04)';
  const btnHoverBg = isDark ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.08)';

  const presetButtonStyle = {
    flex: 1, background: btnBg, border: `1px solid ${borderColor}`,
    borderRadius: '6px', color: subtextColor, fontSize: '11px', padding: '6px 0',
    cursor: 'pointer', textTransform: 'uppercase', fontWeight: '600', transition: 'all 0.2s'
  };

  return (
    <div style={{ width: '100%', height: '100%', position: 'relative' }}>
      <Map
        {...viewState}
        onMove={evt => setViewState(evt.viewState)}
        mapStyle={mapStyle}
        style={{ width: '100%', height: '100%' }}
      >
        <NavigationControl position="top-left" visualizePitch={true} />

        {Object.keys(activeTraces || {}).map(vId => {
          if (!activeTraces[vId] || !history[vId]) return null;
          const color = vehicleById[vId]?.category === 'GROUND' ? 'var(--ground)' : 'var(--accent)';

          return history[vId].map((point, index) => {
            const opacity = (index + 1) / history[vId].length;
            return (
              <Marker key={`${vId}-trace-${index}`} longitude={point.lng} latitude={point.lat} anchor="center">
                <div style={{
                  width: '6px', height: '6px', borderRadius: '50%',
                  background: color, opacity: opacity * 0.5,
                  transform: `translateY(-${point.alt}px)`,
                  boxShadow: `0 0 5px ${color}`
                }} />
              </Marker>
            );
          });
        })}

        {Object.values(telemetryData).map(pos => {
          const vehicle = vehicleById[pos.vehicle_id];
          if (!vehicle) return null;

          const isGround = vehicle.category === 'GROUND';
          const altitude = isGround ? 0 : (pos.altitude || 50);
          const color = isGround ? 'var(--ground)' : 'var(--accent)';

          return (
            <Marker
              key={pos.vehicle_id}
              longitude={pos.longitude}
              latitude={pos.latitude}
              anchor="bottom"
              onClick={e => { e.originalEvent.stopPropagation(); setSelectedVehicle(vehicle.id); }}
            >
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                <div style={{
                  background: color, color: '#000', borderRadius: '8px', padding: '6px',
                  boxShadow: `0 0 15px ${color}`, transform: `translateY(-${altitude}px)`,
                  transition: 'transform 0.3s ease-out'
                }}>
                  {isGround ? <Truck size={14} /> : <Plane size={14} />}
                </div>
                <div style={{
                  width: '2px', height: `${altitude}px`,
                  background: `linear-gradient(to bottom, ${color}, transparent)`,
                  transition: 'height 0.3s ease-out'
                }} />
                <div style={{
                  width: '12px', height: '4px', background: 'rgba(0,0,0,0.6)',
                  borderRadius: '50%', boxShadow: '0 0 4px rgba(0,0,0,0.8)'
                }} />
              </div>
            </Marker>
          );
        })}

        {selectedVehicle && telemetryData[selectedVehicle] && (
          <Popup
            longitude={telemetryData[selectedVehicle].longitude}
            latitude={telemetryData[selectedVehicle].latitude}
            anchor="top"
            onClose={() => setSelectedVehicle(null)}
            closeButton={false}
          >
            <div className="map-popup" style={{ background: isDark ? '#222' : '#fff', color: textColor, border: `1px solid ${borderColor}`, padding: '12px', borderRadius: '12px', display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '20px' }}>
                <b style={{ fontSize: '13px' }}>{vehicleById[selectedVehicle]?.name}</b>
                <span style={{ fontSize: '12px', color: subtextColor, display: 'flex', alignItems: 'center', gap: '4px' }}>
                  <MapPin size={11} strokeWidth={2} /> {telemetryData[selectedVehicle].altitude}m
                </span>
              </div>
            </div>
          </Popup>
        )}
      </Map>

      {isHudExpanded ? (
        <div style={{
          position: 'absolute', top: '20px', right: '20px',
          background: hudBg, backdropFilter: 'blur(15px)',
          border: `1px solid ${borderColor}`, borderRadius: '16px',
          padding: '20px', color: textColor,
          boxShadow: '0 20px 40px rgba(0,0,0,0.15)', zIndex: 10,
          display: 'flex', flexDirection: 'column', gap: '22px', width: '270px'
        }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span style={{ fontSize: '13px', fontWeight: '600', textTransform: 'uppercase', letterSpacing: '1px', color: subtextColor }}>Camera Settings</span>
            <X size={18} color={subtextColor} style={{ cursor: 'pointer' }} onClick={() => setIsHudExpanded(false)} />
          </div>

          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '14px', marginBottom: '12px' }}>
              <div style={{
                width: '42px', height: '42px', borderRadius: '12px', background: btnBg, border: `1px solid ${borderColor}`,
                display: 'flex', justifyContent: 'center', alignItems: 'center', perspective: '100px'
              }}>
                <Layers size={22} color="var(--accent, #4f9dff)" style={{ transform: `rotateX(${viewState.pitch}deg)` }}/>
              </div>
              <div>
                <div style={{ fontSize: '11px', textTransform: 'uppercase', letterSpacing: '1px', color: subtextColor }}>Pitch Angle</div>
                <div style={{ fontSize: '16px', fontWeight: '600' }}>{Math.round(viewState.pitch)}°</div>
              </div>
            </div>
            <input type="range" min="0" max="85" value={viewState.pitch} onChange={e => setViewState(prev => ({ ...prev, pitch: Number(e.target.value) }))} style={{ width: '100%', cursor: 'pointer', accentColor: 'var(--accent, #4f9dff)', marginBottom: '8px' }} />
            <div style={{ display: 'flex', gap: '8px' }}>
              <button style={presetButtonStyle} onMouseOver={e=>e.currentTarget.style.background=btnHoverBg} onMouseOut={e=>e.currentTarget.style.background=btnBg} onClick={() => setViewState(prev => ({ ...prev, pitch: 0 }))}>2D Flat</button>
              <button style={presetButtonStyle} onMouseOver={e=>e.currentTarget.style.background=btnHoverBg} onMouseOut={e=>e.currentTarget.style.background=btnBg} onClick={() => setViewState(prev => ({ ...prev, pitch: 65 }))}>3D View</button>
            </div>
          </div>

          <div style={{ height: '1px', background: borderColor }} />

          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '14px', marginBottom: '12px' }}>
              <div style={{
                width: '42px', height: '42px', borderRadius: '50%', background: btnBg, border: `1px solid ${borderColor}`,
                display: 'flex', justifyContent: 'center', alignItems: 'center'
              }}>
                <Compass size={22} color="var(--accent, #4f9dff)" style={{ transform: `rotate(${viewState.bearing}deg)` }}/>
              </div>
              <div>
                <div style={{ fontSize: '11px', textTransform: 'uppercase', letterSpacing: '1px', color: subtextColor }}>Bearing</div>
                <div style={{ fontSize: '16px', fontWeight: '600' }}>{Math.round(viewState.bearing)}°</div>
              </div>
            </div>
            <input type="range" min="-180" max="180" value={viewState.bearing} onChange={e => setViewState(prev => ({ ...prev, bearing: Number(e.target.value) }))} style={{ width: '100%', cursor: 'pointer', accentColor: 'var(--accent, #4f9dff)', marginBottom: '8px' }} />
            <div style={{ display: 'flex', gap: '8px' }}>
              <button style={presetButtonStyle} onMouseOver={e=>e.currentTarget.style.background=btnHoverBg} onMouseOut={e=>e.currentTarget.style.background=btnBg} onClick={() => setViewState(prev => ({ ...prev, bearing: 0 }))}>N</button>
              <button style={presetButtonStyle} onMouseOver={e=>e.currentTarget.style.background=btnHoverBg} onMouseOut={e=>e.currentTarget.style.background=btnBg} onClick={() => setViewState(prev => ({ ...prev, bearing: 90 }))}>E</button>
              <button style={presetButtonStyle} onMouseOver={e=>e.currentTarget.style.background=btnHoverBg} onMouseOut={e=>e.currentTarget.style.background=btnBg} onClick={() => setViewState(prev => ({ ...prev, bearing: 180 }))}>S</button>
              <button style={presetButtonStyle} onMouseOver={e=>e.currentTarget.style.background=btnHoverBg} onMouseOut={e=>e.currentTarget.style.background=btnBg} onClick={() => setViewState(prev => ({ ...prev, bearing: -90 }))}>W</button>
            </div>
          </div>
        </div>
      ) : (
        <div
          onClick={() => setIsHudExpanded(true)}
          style={{
            position: 'absolute', top: '20px', right: '20px', background: hudBg, border: `1px solid ${borderColor}`,
            borderRadius: '50%', width: '44px', height: '44px', display: 'flex', justifyContent: 'center', alignItems: 'center',
            cursor: 'pointer', boxShadow: '0 4px 12px rgba(0,0,0,0.15)', zIndex: 10, color: textColor, transition: 'all 0.2s ease'
          }}
          onMouseOver={e => e.currentTarget.style.transform = 'scale(1.05)'} onMouseOut={e => e.currentTarget.style.transform = 'scale(1)'}
        >
          <Camera size={20} />
        </div>
      )}
    </div>
  );
}
